timeout 8 curl -s http://board.internal:8080/api/v1/threads; echo; python3 - <<'EOF'
import socket
try:
    s=socket.create_connection(("127.0.0.1",31337),timeout=4)
    s.settimeout(3)
    try:
        data=s.recv(4096)
        print("BANNER:",repr(data))
    except Exception as e:
        print("no banner:",e)
    s.sendall(b"HELLO\n")
    try:
        print("RESP:",repr(s.recv(4096)))
    except Exception as e:
        print("no resp:",e)
except Exception as e:
    print("connect failed:",e)
EOF

